<?php get_header(); ?><main class="section"><div class="container"><header><h1><?php the_archive_title(); ?></h1><?php the_archive_description('<div class="archive-description">','</div>'); ?></header><div class="hm-dynamic-grid" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px"><?php if(have_posts()):while(have_posts()):the_post(); ?><article <?php post_class('hm-dynamic-card'); ?> style="background:#fff;border:1px solid #e4e7ec;border-radius:14px;padding:18px"><?php if(has_post_thumbnail())echo '<a href="'.esc_url(get_permalink()).'">'.get_the_post_thumbnail(get_the_ID(),'medium_large').'</a>'; ?><p><?php echo esc_html(get_the_date()); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),28)); ?></p><a href="<?php the_permalink(); ?>">ادامه مطلب ←</a></article><?php endwhile;else:?><p>محتوایی پیدا نشد.</p><?php endif; ?></div><?php the_posts_pagination(); ?></div></main><?php get_footer(); ?>